4. Implement relevance scoring algorithm:
```typescript
function scoreRelevance(doc: any, query: string, projectState: ProjectState): number {
  let score = doc.score; // Base vector similarity score

  // Boost for recency
  const docAge = Date.now() - new Date(doc.payload.timestamp).getTime();
  const recencyBoost = Math.max(0, 1 - (docAge / (7 * 24 * 60 * 60 * 1000))); // Boost for docs less than a week old

  // Boost for task relevance
  const taskRelevance = projectState.activeTasks.some(taskId => {
    const task = taskTracker.getTask(taskId);
    return task && task.files.includes(doc.payload.file_path);
  }) ? 1.5 : 1;

  return score * (1 + recencyBoost) * taskRelevance;
}
```

