1. Design meta-agent coordination system:
```typescript
interface MetaAgentContext {
  agentId: string;
  specialization: string;
  currentTask: string;
  knowledgeBase: {
    key: string;
    value: any;
    timestamp: Date;
  }[];
}

class MetaAgentCoordinator {
  private agents: Map<string, MetaAgentContext> = new Map();

  registerAgent(agentId: string, specialization: string): void {
    this.agents.set(agentId, {
      agentId,
      specialization,
      currentTask: '',
      knowledgeBase: []
    });
  }

  updateAgentTask(agentId: string, task: string): void {
    const agent = this.agents.get(agentId);
    if (agent) {
      agent.currentTask = task;
    }
  }

  shareKnowledge(agentId: string, key: string, value: any): void {
    const agent = this.agents.get(agentId);
    if (agent) {
      const existingIndex = agent.knowledgeBase.findIndex(item => item.key === key);
      if (existingIndex >= 0) {
        agent.knowledgeBase[existingIndex] = { key, value, timestamp: new Date() };
      } else {
        agent.knowledgeBase.push({ key, value, timestamp: new Date() });
      }
    }
  }

  getSharedKnowledge(key: string): any[] {
    return Array.from(this.agents.values())
      .flatMap(agent => agent.knowledgeBase)
      .filter(item => item.key === key)
      .map(item => item.value);
  }

  getAgentContext(agentId: string): MetaAgentContext | undefined {
    return this.agents.get(agentId);
  }

  getActiveAgents(): MetaAgentContext[] {
    return Array.from(this.agents.values());
  }
}
```

