async function getCodeContext(filePath: string, lineNumber: number): Promise<any> {
  // Get file content
  const fileContent = await fs.readFile(filePath, 'utf8');
  const lines = fileContent.split('\n');

  // Extract context around the specified line
  const contextStart = Math.max(0, lineNumber - 10);
  const contextEnd = Math.min(lines.length, lineNumber + 10);
  const codeContext = lines.slice(contextStart, contextEnd).join('\n');

  // Get related documentation
  const queryEmbedding = await embedQuery(codeContext);
  const relatedDocs = await searchVectors('code_snippets', queryEmbedding, 3, {
    must: [
      {
        key: 'file_path',
        match: {
          value: filePath
        }
      }
    ]
  });

  return {
    codeContext,
    lineNumber,
    filePath,
    relatedDocs
  };
}

