  trackOperation(operation: string, durationMs: number, resourceUsage?: {cpu?: number, memory?: number}): void {
    this.metrics.push({
      operation,
      timestamp: new Date(),
      durationMs,
      resourceUsage
    });
  }

  getPerformanceStats(): any {
    // Group by operation
    const operationStats = {};

    this.metrics.forEach(metric => {
      if (!operationStats[metric.operation]) {
        operationStats[metric.operation] = {
          count: 0,
          totalDuration: 0,
          maxDuration: 0,
          minDuration: Infinity
        };
      }

      const stats = operationStats[metric.operation];
      stats.count++;
      stats.totalDuration += metric.durationMs;
      stats.maxDuration = Math.max(stats.maxDuration, metric.durationMs);
      stats.minDuration = Math.min(stats.minDuration, metric.durationMs);
    });

    // Calculate averages
    Object.values(operationStats).forEach((stats: any) => {
      stats.avgDuration = stats.totalDuration / stats.count;
    });

    return operationStats;
  }
}
