class AccuracyTracker {
  private relevanceScores: {
    query: string;
    results: {
      documentId: string;
      relevanceScore: number;
      userFeedback?: boolean;
    }[];
  }[] = [];

  recordQueryResults(query: string, results: any[]): void {
    this.relevanceScores.push({
      query,
      results: results.map(r => ({
        documentId: r.id,
        relevanceScore: r.score
      }))
    });
  }

  recordUserFeedback(query: string, documentId: string, relevant: boolean): void {
    const queryRecord = this.relevanceScores.find(r => r.query === query);
    if (queryRecord) {
      const result = queryRecord.results.find(r => r.documentId === documentId);
      if (result) {
        result.userFeedback = relevant;
      }
    }
  }

  calculateAccuracyMetrics(): any {
    const resultsWithFeedback = this.relevanceScores
      .flatMap(r => r.results)
      .filter(r => r.userFeedback !== undefined);

    if (resultsWithFeedback.length === 0) {
      return { precision: null, recall: null, f1Score: null };
    }

    const truePositives = resultsWithFeedback.filter(r => r.userFeedback === true).length;
    const falsePositives = resultsWithFeedback.filter(r => r.userFeedback === false).length;

    const precision = truePositives / (truePositives + falsePositives);

    // Note: Recall requires knowing all relevant documents, which is difficult
    // This is a simplified calculation
    const recall = 0.8; // Placeholder

    const f1Score = 2 * (precision * recall) / (precision + recall);

    return { precision, recall, f1Score };
  }
}
